from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Best path found so far
    best_path = None

    def dfs(r: int, c: int, path: List[int]):
        nonlocal best_path
        # If we already have a best path and current path is lexicographically larger, prune
        if best_path is not None:
            # Compare current path with best_path up to min length
            for i in range(len(path)):
                if path[i] < best_path[i]:
                    break
                elif path[i] > best_path[i]:
                    return  # current path is worse, prune
            # If equal so far, we need to continue but cannot improve best_path yet

        if len(path) == k:
            # Found a complete path of length k
            if best_path is None or path < best_path:
                best_path = path[:]
            return

        # Explore neighbors
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                path.append(grid[nr][nc])
                dfs(nr, nc, path)
                path.pop()

    # Try starting from every cell
    for i in range(n):
        for j in range(n):
            dfs(i, j, [grid[i][j]])

    return best_path
